allMsgs.forEach(el => console.log(el.textContent));

// Selector ترکیبی مثل CSS
const saveBtn = document.querySelector('#app button[data-action=save]');

// جستجو داخل یک عنصر مشخص (نه کل صفحه)
const innerBtn = app.querySelector('button');

// اگر پیدا نشود null برمی‌گرداند → همیشه چک کن
const box = document.querySelector('.not-exists');
if (box) box.textContent = 'پیدا شد';
```

نکته‌ها:
- `getElementById` برای id کمی سریع‌تر است ولی `querySelector` انعطاف بیشتری دارد.
- خروجی `querySelectorAll` یک NodeList است که `forEach` دارد اما آرایه نیست؛ برای متدهایی مثل map اول با `[...nodeList]` یا `Array.from` به آرایه تبدیلش کن.
- انتخابگرها با CSS یکسان‌اند، پس هر چیزی که در CSS می‌نویسی اینجا هم کار می‌کند.

@container lets a component style itself based on its *container's* size instead of the viewport, making truly reusable components. The parent needs container-type: inline-size to establish the query context.

```css
.card-host { container-type: inline-size; }
@container (min-width: 420px) {
  .card { display: grid; grid-template-columns: 96px 1fr; }
}
```

